14		"github.com/gorilla/feeds"
15		"github.com/labstack/echo/v5"
16	
17		"github.com/usememos/memos/internal/markdown"
18		"github.com/usememos/memos/internal/profile"
19		storepb "github.com/usememos/memos/proto/gen/store"
20		"github.com/usememos/memos/store"
21	)
22	
23	const (
24		maxRSSItemCount      = 100
25		defaultCacheDuration = 1 * time.Hour
26		maxCacheSize         = 50 // Maximum number of cached feeds
27	)
28	
29	var (
30		// Regex to match markdown headings at the start of a line.
31		markdownHeadingRegex = regexp.MustCompile(`^#{1,6}\s*`)
32	)
33	
34	// cacheEntry represents a cached RSS feed with expiration.
35	type cacheEntry struct {
36		content      string
37		etag         string
38		lastModified time.Time
39		createdAt    time.Time
40	}
41	
42	type RSSService struct {
43		Profile         *profile.Profile
44		Store           *store.Store
45		MarkdownService markdown.Service
46	
47		// Cache for RSS feeds
48		cache      map[string]*cacheEntry
49		cacheMutex sync.RWMutex
50	}
51	
52	type RSSHeading struct {
53		Title       string
54		Description string
55		Language    string
56	}
57	
58	func NewRSSService(profile *profile.Profile, store *store.Store, markdownService markdown.Service) *RSSService {
59		return &RSSService{
60			Profile:         profile,
61			Store:           store,
62			MarkdownService: markdownService,
63			cache:           make(map[string]*cacheEntry),
64		}
65	}
66	
67	func (s *RSSService) RegisterRoutes(g *echo.Group) {
68		g.GET("/explore/rss.xml", s.GetExploreRSS)
69		g.GET("/u/:username/rss.xml", s.GetUserRSS)
70	}
71	
72	func (s *RSSService) GetExploreRSS(c *echo.Context) error {
73		ctx := c.Request().Context()
74		cacheKey := "explore"
75	
76		// Check cache first
77		if cached := s.getFromCache(cacheKey); cached != nil {
78			// Check ETag for conditional request
79			if c.Request().Header.Get("If-None-Match") == cached.etag {
80				return c.NoContent(http.StatusNotModified)
81			}
82			s.setRSSHeaders(c, cached.etag, cached.lastModified)
83			return c.String(http.StatusOK, cached.content)
84		}
85	
86		normalStatus := store.Normal
87		limit := maxRSSItemCount
88		memoFind := store.FindMemo{
89			RowStatus:       &normalStatus,
90			VisibilityList:  []store.Visibility{store.Public},
91			ExcludeComments: true,
92			Limit:           &limit,
93		}
94		memoList, err := s.Store.ListMemos(ctx, &memoFind)
95		if err != nil {
96			return echo.NewHTTPError(http.StatusInternalServerError, "Failed to find memo list").Wrap(err)
97		}
98	
99		baseURL := c.Scheme() + "://" + c.Request().Host
100		rss, lastModified, err := s.generateRSSFromMemoList(ctx, memoList, baseURL, nil)
101		if err != nil {
102			return echo.NewHTTPError(http.StatusInternalServerError, "Failed to generate rss").Wrap(err)
103		}
104	
105		// Cache the result
106		etag := s.putInCache(cacheKey, rss, lastModified)
107		s.setRSSHeaders(c, etag, lastModified)
108		return c.String(http.StatusOK, rss)
109	}
